@Test
@Transactional
void 컬럼_수() {
    record C(String name, Runnable r) {}
    for (C c : List.of(
            new C("엔티티",  () -> memberRepository.findByAge(10)),
            new C("닫힌",    () -> memberRepository.findProjectionByAge(10)),
            new C("default", () -> memberRepository.findDefaultByAge(10)),
            new C("열린",    () -> memberRepository.findOpenByAge(10)))) {
        em.clear();
        System.out.printf("%-8s %d개%n", c.name(),
                sqlCapture.columnCount(c.r()));
    }
}

